import { createHash } from 'node:crypto';
import { posix } from 'node:path';
import { Readable } from 'node:stream';

import { Client, type SFTPWrapper } from 'ssh2';

import type { ServerConfig } from '../config';
import type { BlobStore } from './types';

type SftpConfig = NonNullable<ServerConfig['sftp']>;

/** Keys are generated by the file service; anything else never reaches the remote disk. */
const SAFE_KEY = /^[a-z0-9-]{8,64}$/;
/** SFTP's "no such file" status code. */
const NO_SUCH_FILE = 2;

const isMissing = (error: unknown) =>
  typeof error === 'object' && error !== null && 'code' in error && error.code === NO_SUCH_FILE;

/** `SHA256:…` — the fingerprint format `ssh-keygen -l` prints. */
export function sshFingerprint(hostKey: Buffer): string {
  return `SHA256:${createHash('sha256').update(hostKey).digest('base64').replace(/=+$/, '')}`;
}

/**
 * A directory on another machine, over SSH (SFTP) — a home computer, a NAS,
 * a VPS. The server signs in with a key (never a password) and checks the
 * machine's host key against SFTP_HOST_FINGERPRINT before sending anything.
 *
 * One SSH connection is opened on first use and shared; when it drops, the
 * next call opens a new one. Files are laid out like the `local` driver
 * (`{dir}/{first two chars}/{key}`) and written beside their final name,
 * then renamed into place. SSH adds a round trip to every read, so put a CDN
 * in front (CDN_BASE_URL) for files that are read often.
 */
export function createSftpBlobStore(config: SftpConfig): BlobStore {
  const root = posix.normalize(config.directory);
  const pathOf = (key: string) =>
    SAFE_KEY.test(key) ? posix.join(root, key.slice(0, 2), key) : null;

  let session: Promise<SFTPWrapper> | null = null;

  /** Opens an SSH connection and its SFTP channel; `drop` runs when either goes away. */
  function connect(drop: () => void): Promise<SFTPWrapper> {
    return new Promise((resolve, reject) => {
      const client = new Client();
      let hostKeyMismatch: string | null = null;
      client
        .on('ready', () => {
          client.sftp((error, sftp) => {
            if (error) {
              client.end();
              reject(error);
              return;
            }
            sftp.on('close', drop);
            resolve(sftp);
          });
        })
        .on('error', (error) => {
          drop();
          reject(
            hostKeyMismatch
              ? new Error(
                  `SFTP host key of ${config.host} is ${hostKeyMismatch}, not SFTP_HOST_FINGERPRINT`,
                )
              : error,
          );
        })
        .on('close', drop);

      void Bun.file(config.privateKeyPath)
        .text()
        .then((privateKey) =>
          client.connect({
            host: config.host,
            port: config.port,
            username: config.username,
            privateKey,
            ...(config.passphrase ? { passphrase: config.passphrase } : {}),
            readyTimeout: 10_000,
            keepaliveInterval: 30_000,
            hostVerifier: (hostKey: Buffer) => {
              const actual = sshFingerprint(hostKey);
              if (actual === config.hostFingerprint) return true;
              hostKeyMismatch = actual;
              return false;
            },
          }),
        )
        .catch((error: unknown) => {
          drop();
          reject(
            new Error(
              `cannot read SFTP_PRIVATE_KEY_PATH (${config.privateKeyPath}): ${String(error)}`,
            ),
          );
        });
    });
  }

  /** The shared SFTP session, opened on first use and again after a drop. */
  function sftp(): Promise<SFTPWrapper> {
    if (!session) {
      const opening = connect(() => {
        if (session === opening) session = null;
      });
      session = opening;
    }
    return session;
  }

  const call = <T>(run: (done: (error: Error | null | undefined, value?: T) => void) => void) =>
    new Promise<T>((resolve, reject) => {
      run((error, value) => (error ? reject(error) : resolve(value as T)));
    });

  async function ensureDir(remote: SFTPWrapper, dir: string): Promise<void> {
    try {
      await call<void>((done) => remote.mkdir(dir, { mode: 0o700 }, (error) => done(error)));
    } catch {
      // Already there (SFTP has no "exists" code for mkdir); the write below
      // fails clearly if the directory really could not be made.
    }
  }

  return {
    async put(key, bytes) {
      const path = pathOf(key);
      if (!path) throw new Error(`not a storage key: ${key}`);
      const remote = await sftp();
      await ensureDir(remote, root);
      await ensureDir(remote, posix.dirname(path));
      const partial = `${path}.partial`;
      await new Promise<void>((resolve, reject) => {
        // Only the account the server signs in as can read or change uploads.
        const stream = remote.createWriteStream(partial, { mode: 0o600 });
        stream.on('error', reject).on('close', () => resolve());
        stream.end(Buffer.from(bytes.buffer, bytes.byteOffset, bytes.byteLength));
      });
      await call<void>((done) => remote.rename(partial, path, (error) => done(error)));
      return key;
    },

    async get(ref) {
      const path = pathOf(ref);
      if (!path) return null;
      const remote = await sftp();
      try {
        await call((done) => remote.stat(path, (error, stats) => done(error, stats)));
      } catch (error) {
        if (isMissing(error)) return null;
        throw error;
      }
      return Readable.toWeb(remote.createReadStream(path)) as unknown as ReadableStream<Uint8Array>;
    },

    async delete(ref) {
      const path = pathOf(ref);
      if (!path) return;
      const remote = await sftp();
      try {
        await call<void>((done) => remote.unlink(path, (error) => done(error)));
      } catch (error) {
        if (!isMissing(error)) throw error;
      }
    },
  };
}
